Abbreviation SEGS := Ubsan.M.loaded_segments.
Module Ly := U1Layout.

Section PM.
Context {AC : AllocCeiling}.
  Context {MI : MallocIface SEGS Ly.L} {ST : StaticsIface SEGS Ly.L}.
  Context {G : grammar} {idesc : Z -> Z -> Prop} {odesc edesc : Z -> Z -> Z -> Prop}
          {generates_type is_ext_inst is_nonsemantic : Z -> bool}
          {ds_rep : AS MI -> mem -> Z -> Z -> Z -> list (Z * Z) -> Prop}.
  Variable CL : pm_calleesU1 SEGS Ly.L MI ST G tcU1 dcU1 nfcU1 HConstsU1.hc ccU1 kcU1
                  idesc odesc edesc generates_type is_ext_inst is_nonsemantic ds_rep.

  Variable PM : parse_module_stmt SEGS Ly.L MI ST kcU1.

  Variable PO : @PmWrapU1.po_callees AC MI ST.
  #[local] Notation cfg fx R pc M model := (mkCfg (@mkst fx R (Z_to_bv 64 pc) M (seg_rom SEGS)) model).
  #[local] Notation po_tail := (PmWrapU1.po_tail CL PM PO).
  #[local] Notation ws_new := (PmWrapU1.ws_new CL).

  Lemma po_core2 : forall (w : @ww AC MI ST) K (fx : FPState) A6 M6 model6 R6 (p3 p4 p5 p6 : Z),
    let sp := v_sp0 w in let b := v_sp0 w - 672 in let words := v_words w in let n := v_n w in
    POPOST w K -> POW w -> pm_budget SEGS Ly.L MI (v_A0 w) n -> 500 <= NMAX MI ->
    ainv MI (v_A0 w) (v_M0 w) (v_model0 w) ->
    (words <> 0 -> words_ok (live MI (v_A0 w)) sp (v_M0 w) words n) ->
    (forall a, zwin words (words + 4 * n) a -> ~ zwin (sp - PO_STK) sp a) ->
    frm_zero (@fp_csr fx) ->
    WS w [(p3, 500); (p4, 100); (p5, 100); (p6, 500)] A6 M6 model6 ->
    pinit b M6 -> vtrip b 216 p3 500 M6 -> vtrip b 240 p4 100 M6 -> vtrip b 264 p5 100 M6 -> tinit b words n M6 ->
    0 < p3 -> 0 < p4 -> 0 < p5 -> 0 < p6 -> p6 + 500 <= alloc_ceiling ->
    getr R6 2%bv = Z_to_bv 64 b -> getr R6 3%bv = Z_to_bv 64 (ly_gp Ly.L) -> getr R6 4%bv = Z_to_bv 64 (ly_tp Ly.L) ->
    getr R6 10%bv = Z_to_bv 64 p6 -> getr R6 8%bv = Z_to_bv 64 (b + 304) ->
    getr R6 24%bv = getr (v_R0 w) 24%bv -> getr R6 25%bv = getr (v_R0 w) 25%bv -> getr R6 26%bv = getr (v_R0 w) 26%bv -> getr R6 27%bv = getr (v_R0 w) 27%bv ->
